package schemagen

import (
	"bytes"
	"fmt"
	"go/format"
	"sort"
	"strconv"
	"strings"

	"github.com/alchemaxinc/terraform-provider-balena/internal/engine"
)

// GENERATED_HEADER marks generated files, following the Go convention.
const GENERATED_HEADER = "// Code generated by schemagen. DO NOT EDIT."

// RESERVED_ATTRIBUTE_NAMES are root attribute names Terraform reserves for meta-arguments.
var RESERVED_ATTRIBUTE_NAMES = map[string]bool{
	"connection":  true,
	"count":       true,
	"depends_on":  true,
	"for_each":    true,
	"lifecycle":   true,
	"provider":    true,
	"provisioner": true,
}

// Descriptors maps a spec to engine descriptors, purely from the spec.
//
// Mapping rules:
//   - A read-only field is Computed.
//   - A hashed field is Sensitive and write-only, because the API returns a hash.
//   - A required field without a server default is Required.
//   - A field with a server default is Optional and Computed.
//   - Any other field is Optional; removing it from configuration clears it.
//   - Integer, foreign key, string and boolean fields are data source filters.
func Descriptors(spec *Spec) ([]engine.Resource, error) {
	out := make([]engine.Resource, 0, len(spec.Resources))
	for _, r := range spec.Resources {
		d := engine.Resource{
			TypeName: r.Name,
			Path:     "/" + spec.APIRoot + "/" + r.Name,
			Description: fmt.Sprintf("Manages one `%s` through the Balena API at `/%s/%s`.",
				stripBackticks(r.Term), spec.APIRoot, r.Name),
			DataSourceDescription: fmt.Sprintf("Looks up one `%s` through the Balena API at `/%s/%s`, "+
				"by `id` or by any combination of the other arguments, which must match exactly one.",
				stripBackticks(r.Term), spec.APIRoot, r.Name),
		}
		for _, f := range r.Fields {
			if f.Name == engine.ID_ATTRIBUTE || RESERVED_ATTRIBUTE_NAMES[f.Name] {
				continue
			}
			d.Attributes = append(d.Attributes, attribute(r, f))
		}
		out = append(out, d)
	}
	sort.Slice(out, func(i, j int) bool { return out[i].TypeName < out[j].TypeName })
	return out, nil
}

func attribute(r Resource, f Field) engine.Attribute {
	a := engine.Attribute{Name: f.Name, Wire: f.Name, Enum: f.Enum}
	switch f.Type {
	case TYPE_INTEGER:
		a.Type = engine.TYPE_INT64
	case TYPE_FOREIGN_KEY:
		a.Type, a.Codec = engine.TYPE_INT64, engine.CODEC_FOREIGN_KEY
	case TYPE_BOOLEAN:
		a.Type = engine.TYPE_BOOL
	case TYPE_JSON:
		a.Type, a.Codec = engine.TYPE_STRING, engine.CODEC_JSON
	default:
		a.Type = engine.TYPE_STRING
	}

	switch {
	case f.ReadOnly:
		a.Mode = engine.MODE_COMPUTED
	case f.Required && !f.ServerDefault:
		a.Mode = engine.MODE_REQUIRED
	case f.ServerDefault && f.Type != TYPE_HASHED:
		a.Mode = engine.MODE_OPTIONAL_COMPUTED
	default:
		a.Mode = engine.MODE_OPTIONAL
	}
	if f.Type == TYPE_HASHED {
		a.Sensitive, a.WriteOnly = true, true
	}
	switch f.Type {
	case TYPE_INTEGER, TYPE_FOREIGN_KEY, TYPE_STRING, TYPE_BOOLEAN:
		a.Filterable = true
	}

	desc := fmt.Sprintf("Field `%s` of `%s` (%s).", stripBackticks(f.Term), stripBackticks(r.Term), stripBackticks(f.SQLType))
	if f.References != "" {
		desc += fmt.Sprintf(" The id of the referenced `%s`.", f.References)
	}
	if len(f.Enum) > 0 {
		values := make([]string, len(f.Enum))
		for i, v := range f.Enum {
			values[i] = stripBackticks(v)
		}
		desc += " One of `" + strings.Join(values, "`, `") + "`."
	}
	switch {
	case f.ReadOnly:
		desc += " Read-only: the API computes it."
	case f.Type == TYPE_HASHED:
		desc += " Write-only: the API stores only a hash."
	case f.ServerDefault:
		desc += " The API fills it when it is omitted."
	}
	a.Description = desc
	return a
}

// Generate renders the descriptors of a spec as Go source.
func Generate(spec *Spec) ([]byte, error) {
	ds, err := Descriptors(spec)
	if err != nil {
		return nil, err
	}
	var b bytes.Buffer
	b.WriteString(GENERATED_HEADER + "\n\n")
	b.WriteString("// Package generated holds the descriptors schemagen derives from schema/api.\n")
	b.WriteString("package generated\n\n")
	b.WriteString("import \"github.com/alchemaxinc/terraform-provider-balena/internal/engine\"\n\n")
	b.WriteString("// RESOURCES describes every resource of the API model.\n")
	b.WriteString("var RESOURCES = []engine.Resource{\n")
	for _, d := range ds {
		fmt.Fprintf(&b, "{\nTypeName: %s,\nPath: %s,\nDescription: %s,\nDataSourceDescription: %s,\nAttributes: []engine.Attribute{\n",
			strconv.Quote(d.TypeName), strconv.Quote(d.Path), strconv.Quote(d.Description), strconv.Quote(d.DataSourceDescription))
		for _, a := range d.Attributes {
			fmt.Fprintf(&b, "{Name: %s, Wire: %s, Type: engine.%s, Codec: engine.%s, Mode: engine.%s",
				strconv.Quote(a.Name), strconv.Quote(a.Wire), typeIdent[a.Type], codecIdent[a.Codec], modeIdent[a.Mode])
			if a.Sensitive {
				b.WriteString(", Sensitive: true")
			}
			if a.WriteOnly {
				b.WriteString(", WriteOnly: true")
			}
			if a.Filterable {
				b.WriteString(", Filterable: true")
			}
			if len(a.Enum) > 0 {
				quoted := make([]string, len(a.Enum))
				for i, e := range a.Enum {
					quoted[i] = strconv.Quote(e)
				}
				fmt.Fprintf(&b, ", Enum: []string{%s}", strings.Join(quoted, ", "))
			}
			fmt.Fprintf(&b, ", Description: %s},\n", strconv.Quote(a.Description))
		}
		b.WriteString("},\n},\n")
	}
	b.WriteString("}\n")
	src, err := format.Source(b.Bytes())
	if err != nil {
		return nil, fmt.Errorf("formatting generated source: %w", err)
	}
	return src, nil
}

var typeIdent = map[engine.AttrType]string{
	engine.TYPE_INT64:  "TYPE_INT64",
	engine.TYPE_STRING: "TYPE_STRING",
	engine.TYPE_BOOL:   "TYPE_BOOL",
}

var codecIdent = map[engine.Codec]string{
	engine.CODEC_PLAIN:       "CODEC_PLAIN",
	engine.CODEC_FOREIGN_KEY: "CODEC_FOREIGN_KEY",
	engine.CODEC_JSON:        "CODEC_JSON",
}

var modeIdent = map[engine.Mode]string{
	engine.MODE_REQUIRED:          "MODE_REQUIRED",
	engine.MODE_OPTIONAL:          "MODE_OPTIONAL",
	engine.MODE_OPTIONAL_COMPUTED: "MODE_OPTIONAL_COMPUTED",
	engine.MODE_COMPUTED:          "MODE_COMPUTED",
}
